#include <iostream>
#include <fstream>
#include <string>
int main() {
    {
        std::ofstream out("demo_text.txt");
        out << "line1\nline2\nline3\n";
    }
    std::ifstream in("demo_text.txt");
    std::string s; int count = 0;
    while (std::getline(in, s)) { std::cout << s << '\n'; ++count; }
    std::cout << "count=" << count << '\n';
}
